        add_hits(hits, route.get("name", ""), bonus)

    ordered = sorted(by_doc_id.values(), key=lambda h: route_scores.get(hit_value(h, "doc_id", ""), 0), reverse=True)
    candidates = ordered[:CANDIDATE_K]
    ctx.candidate_pool = len(candidates)

    protected = []
    protected_seen = {}
    for hit in candidates:
        doc_id = hit_value(hit, "doc_id", "")
        if doc_id in protected_ids and doc_id not in protected_seen:
            protected.append(hit)
            protected_seen[doc_id] = True
    protected = protected[:4]

    rerank_input = []
    protected_seen = {}
    for hit in protected:
        protected_seen[hit_value(hit, "doc_id", "")] = True
    for hit in candidates:
        if hit_value(hit, "doc_id", "") not in protected_seen:
            rerank_input.append(hit)

    reranked = ctx.ranking.rerank(query, rerank_input, top_k=TOP_K)
    ranked_hits = []
    seen = {}
    for hit in protected + reranked:
        doc_id = hit_value(hit, "doc_id", "")
        if doc_id and doc_id not in seen:
            ranked_hits.append(hit)
            seen[doc_id] = True
        if len(ranked_hits) >= TOP_K:
            break

    ctx.log("reflection", {
        "candidate_pool": len(candidates),
        "protected_exact_authority_docs": len(protected),
        "final_hits": len(ranked_hits),
        "notes": "Preserved exact SEC/CVE and authority evidence before reranking; joined customer blockers, tracked CVE, and release guidance through bounded hybrid routes.",
    })

    return {"hits": ranked_hits, "candidates": candidates}
